#include<bits/stdc++.h>
#define int long long
using namespace std;
struct 符石{
    int a,b;
    int cnt;
    void read(int i){
        cin>>a>>b;
        cnt=i;
    }
}a[200005];
int n,k=0;
map<int,bool> lyy;
signed main(){
    ios::sync_with_stdio(0);
    cin.tie(0);cout.tie(0);
    cin>>n;
    for(int i=1;i<=n;i++)
        a[i].read(i);
    sort(a+1,a+n+1,[](struct 符石 x,struct 符石 y){
        int k1=x.a*y.b,k2=y.a*x.b;
        if(k1==k2) return x.cnt<y.cnt;
        return (bool)(k1<k2);
    });
    int s1=0,s2=0;
    for(int i=1;i<=n;i++){
        s2+=s1*a[i].b;
        s1+=a[i].a;
    }
    cout<<s2<<' ';
    for(int i=1;i<=n;i++){
        if(lyy[a[i].b]==0)
            k++;
        lyy[a[i].b]=1;
    }
    cout<<k<<'\n';
    for(int i=1;i<=n;i++)
        cout<<a[i].cnt<<' ';
    return 0;
}
